import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    // Mapeamento de faces opostas:
    // A (0) <-> F (5)
    // B (1) <-> D (3)
    // C (2) <-> E (4)
    private static final int[] OPP = {5, 3, 4, 1, 2, 0};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) return;

        int n = Integer.parseInt(line.trim());
        int[][] dice = new int[n][6];

        for (int i = 0; i < n; i++) {
            line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line == null) break;
            StringTokenizer st = new StringTokenizer(line);
            for (int j = 0; j < 6; j++) {
                dice[i][j] = Integer.parseInt(st.nextToken());
            }
        }

        int maxSum = 0;

        // O primeiro dado pode ter qualquer uma de suas 6 faces na base
        for (int bottomFaceIdx = 0; bottomFaceIdx < 6; bottomFaceIdx++) {
            int currentSum = 0;
            int currentBottomVal = dice[0][bottomFaceIdx];
            int currentTopVal = dice[0][OPP[bottomFaceIdx]];

            currentSum += getMaxLateral(currentBottomVal, currentTopVal);

            for (int i = 1; i < n; i++) {
                int baseVal = currentTopVal;
                int baseIdx = -1;
                for (int j = 0; j < 6; j++) {
                    if (dice[i][j] == baseVal) {
                        baseIdx = j;
                        break;
                    }
                }
                int topVal = dice[i][OPP[baseIdx]];
                currentSum += getMaxLateral(baseVal, topVal);
                currentTopVal = topVal;
            }

            if (currentSum > maxSum) {
                maxSum = currentSum;
            }
        }

        System.out.println(maxSum);
    }

    private static int getMaxLateral(int v1, int v2) {
        if (v1 != 6 && v2 != 6) return 6;
        if (v1 != 5 && v2 != 5) return 5;
        return 4;
    }
}
```

